using System.ComponentModel.DataAnnotations;
namespace Kaizen.Web.ViewModels;

public class GoalFormViewModel { public int Id { get; set; } [Required(ErrorMessage = "Ingresá un título.")] public string Titulo { get; set; } = ""; [Required(ErrorMessage = "Ingresá una descripción.")] public string Descripcion { get; set; } = ""; [Range(1, int.MaxValue, ErrorMessage = "Seleccioná un área.")] public int AreaPersonalId { get; set; } [Required(ErrorMessage = "Explicá por qué es importante.")] public string PorQueEsImportante { get; set; } = ""; [Required(ErrorMessage = "Describí tu situación actual.")] public string SituacionActual { get; set; } = ""; [Required(ErrorMessage = "Indicá el resultado esperado.")] public string ResultadoEsperado { get; set; } = ""; public DateOnly FechaInicio { get; set; } = DateOnly.FromDateTime(DateTime.Today); public DateOnly? FechaObjetivo { get; set; } [Required(ErrorMessage = "Indicá cómo vas a medir el progreso.")] public string MetricaProgreso { get; set; } = ""; }
